={{ (() => {
  const body = $('Incoming Feedback Webhook').first().json.body;
  const MAX_RECORDS = Number($json.max_records) || 25, MAX_CHARS = Number($json.max_chars) || 20000;
  const errors = {};
  let input = [];
  if (body && Array.isArray(body.records)) input = body.records;
  else if (body && typeof body === 'object' && !Array.isArray(body) && Object.keys(body).length) input = [body];

  if (input.length === 0) errors.records = 'Send {"records": [...]} with at least one record, or a single record object';
  if (input.length > MAX_RECORDS) errors.records = 'Max ' + MAX_RECORDS + ' records per request (got ' + input.length + ')';

  const batchId = 'BATCH-' + $now.toFormat('yyyyMMdd-HHmmss') + '-' + $execution.id;
  const records = [];
  const seen = new Set();
  let duplicates = 0;
  input.slice(0, MAX_RECORDS).forEach((r, i) => {
    const at = 'records[' + i + ']';
    if (!r || typeof r !== 'object' || Array.isArray(r)) { errors[at] = 'Must be an object'; return; }
    const text = r.text ?? r.content ?? r.message ?? r.feedback ?? r.comment ?? r.description;
    if (typeof text !== 'string' || !text.trim()) { errors[at + '.text'] = 'Required non-empty string (text | content | message | feedback | comment | description)'; return; }
    if (text.length > MAX_CHARS) { errors[at + '.text'] = 'Max ' + MAX_CHARS + ' characters'; return; }
    const id = r.id ?? r.external_id;
    if (id != null && (typeof id === 'object' || String(id).length > 100)) { errors[at + '.id'] = 'Must be a string or number, max 100 characters'; return; }
    const source = String(r.source ?? body.source ?? 'api').trim().slice(0, 50) || 'api';
    const ref = id != null && String(id).trim() ? String(id).trim() : 'h-' + text.trim().toLowerCase().replace(/\s+/g, ' ').hash('sha256').slice(0, 16);
    const key = source + ':' + ref;
    if (seen.has(key)) { duplicates++; return; }
    seen.add(key);
    records.push({
      record_key: key,
      batch_id: batchId,
      source,
      author: String(r.author ?? r.email ?? r.name ?? '').slice(0, 200),
      raw_text: text,
      received_at: $now.toISO()
    });
  });

  const valid = Object.keys(errors).length === 0;
  return { valid, errors, batch_id: batchId, count: records.length, duplicates, records: valid ? records : [] };
})() }}

={{ (() => {
  let t = String($json.raw_text ?? '')
    .replace(/<(script|style)[^>]*>[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|tr|h[1-6])>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  const found = {};
  const mask = (re, label, keep) => {
    t = t.replace(re, (m) => {
      if (keep && keep(m)) return m;
      found[label] = (found[label] || 0) + 1;
      return '[' + label + ']';
    });
  };
  const digits = (m) => m.replace(/\D/g, '');
  const failsLuhn = (m) => {
    const d = digits(m);
    let sum = 0;
    for (let i = 0; i < d.length; i++) {
      let n = Number(d[d.length - 1 - i]);
      if (i % 2) { n *= 2; if (n > 9) n -= 9; }
      sum += n;
    }
    return sum % 10 !== 0;
  };
  mask(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, 'EMAIL');
  mask(/\b[A-Z]{2}\d{2}(?: ?[A-Z0-9]{4}){2,7}(?: ?[A-Z0-9]{1,3})?\b/g, 'IBAN');
  mask(/\b\d(?:[ -]?\d){12,18}\b/g, 'CARD', failsLuhn);
  mask(/(?:\+|\b0|\(\d)[\d\s().-]{7,}\d/g, 'PHONE', (m) => digits(m).length < 9 || digits(m).length > 15);
  mask(/\b\d{3}[-.\s]\d{3}[-.\s]\d{4}\b/g, 'PHONE');
  return { text: t, pii: Object.entries(found).map(([k, n]) => k.toLowerCase() + ' x' + n).join(', ') };
})() }}

parameters.text:
=Triage this customer message.

Source: {{ $json.source }}
Personal data was masked as [EMAIL], [PHONE], [CARD] or [IBAN] before you received it.

<message>
{{ $json.redacted.text.slice(0, 6000) }}
</message>

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "summary": {
      "type": "string",
      "description": "Neutral 1-2 sentence summary, max 300 characters"
    },
    "category": {
      "type": "string",
      "enum": [
        "bug",
        "feature_request",
        "billing",
        "account",
        "how_to",
        "praise",
        "complaint",
        "spam",
        "other"
      ]
    },
    "sentiment": {
      "type": "string",
      "enum": [
        "positive",
        "neutral",
        "negative"
      ]
    },
    "priority": {
      "type": "string",
      "enum": [
        "low",
        "medium",
        "high",
        "urgent"
      ]
    },
    "churn_risk": {
      "type": "boolean"
    },
    "suggested_action": {
      "type": "string",
      "description": "One concrete next step, max 150 characters; empty for spam"
    },
    "keywords": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Up to 5 lowercase keywords"
    },
    "language": {
      "type": "string",
      "description": "ISO 639-1 code of the original message"
    },
    "residual_pii": {
      "type": "boolean"
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    }
  },
  "required": [
    "summary",
    "category",
    "sentiment",
    "priority",
    "churn_risk",
    "suggested_action",
    "keywords",
    "language",
    "residual_pii",
    "confidence"
  ],
  "additionalProperties": false
}

assignments.value:
={{ (() => {
  const o = $json.output;
  if (!o?.category || o.category === 'spam') return 'no';
  const cfg = $('Triage Settings').first().json;
  const rank = { low: 0, medium: 1, high: 2, urgent: 3 };
  const min = rank[String(cfg.alert_min_priority ?? 'high').toLowerCase()] ?? 2;
  const byPriority = (rank[o.priority] ?? 0) >= min;
  const byChurn = cfg.alert_on_churn_risk !== false && o.churn_risk === true;
  return byPriority || byChurn ? 'yes' : 'no';
})() }}

