  const rows = $('Map to Sheet Row').all().map(i => i.json)
    .filter(r => r['Needs Attention'] === 'yes')
    .sort((a, b) => (rank[b['Priority']] ?? 0) - (rank[a['Priority']] ?? 0));
  const doc = $('Upsert to Feedback Sheet').params.documentId ?? {};
  const sheetUrl = doc.cachedResultUrl || (String(doc.value ?? '').startsWith('http') ? String(doc.value) : 'https://docs.google.com/spreadsheets/d/' + doc.value);
  const cell = 'padding:10px 8px;border-top:1px solid #e5e5e5;vertical-align:top';
  const body = rows.map(r => '<tr>' +
    '<td style="' + cell + ';white-space:nowrap"><b style="color:' + (color[r['Priority']] ?? '#444') + '">' + esc(r['Priority']).toUpperCase() + '</b><br><span style="color:#666">' + esc(r['Category']) + '</span>' + (r['Churn Risk'] === 'yes' ? '<br><span style="color:#b00020">churn risk</span>' : '') + '</td>' +
    '<td style="' + cell + '">' + esc(r['Summary']) +
      (r['Suggested Action'] ? '<br><span style="color:#0b6e4f">&rarr; ' + esc(r['Suggested Action']) + '</span>' : '') +
