assignments.value:
={{ (() => {
  const cfg = $('Digest Settings').first().json;
  const hours = Number(cfg.window_hours) || 24;
  const end = $now;
  const start = end.minus({ hours });
  const prevStart = end.minus({ hours: hours * 2 });
  const rows = $('Read Feedback Rows').all().map(i => i.json).filter(r => r['Record Key']);
  const cur = [];
  const prev = [];
  for (const r of rows) {
    const at = DateTime.fromISO(String(r['Received At'] ?? ''));
    if (!at.isValid) continue;
    if (at >= start && at <= end) cur.push(r);
    else if (at >= prevStart && at < start) prev.push(r);
  }
  const yes = (v) => String(v).toLowerCase() === 'yes';
  const tally = (list, col) => list.reduce((m, r) => { const k = String(r[col] || 'unknown'); m[k] = (m[k] || 0) + 1; return m; }, {});
  const catNow = tally(cur, 'Category');
  const catBefore = tally(prev, 'Category');
  const categories = [...new Set([...Object.keys(catNow), ...Object.keys(catBefore)])]
    .map(c => ({ category: c, now: catNow[c] || 0, before: catBefore[c] || 0 }))
    .sort((a, b) => b.now - a.now || b.before - a.before);
  const spikes = categories.filter(c => c.category !== 'spam' && c.now >= 3 && c.now >= 2 * Math.max(c.before, 1)).map(c => c.category);
  const negShare = (list) => list.length ? Math.round(100 * list.filter(r => r['Sentiment'] === 'negative').length / list.length) : 0;
  const kw = {};
  cur.forEach(r => String(r['Keywords'] || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean).forEach(k => { kw[k] = (kw[k] || 0) + 1; }));
  const rank = { urgent: 3, high: 2, medium: 1, low: 0 };
  const byPriority = (a, b) => (rank[b['Priority']] ?? -1) - (rank[a['Priority']] ?? -1);
  return {
    window_hours: hours,
    window_start: start.toFormat('yyyy-MM-dd HH:mm'),
    window_end: end.toFormat('yyyy-MM-dd HH:mm ZZZZ'),
    total: cur.length,
    total_before: prev.length,
    categories,
    spikes,
    negative_share: negShare(cur),
    negative_share_before: negShare(prev),
    churn_risk: cur.filter(r => yes(r['Churn Risk'])).length,
    needs_review: cur.filter(r => yes(r['Needs Review'])).length,
    ai_failed: cur.filter(r => r['AI Status'] === 'FAILED').length,
    top_keywords: Object.entries(kw).sort((a, b) => b[1] - a[1]).slice(0, 8).map(([k, n]) => k + ' (' + n + ')'),
    attention: cur.filter(r => yes(r['Needs Attention'])).sort(byPriority).slice(0, 10)
      .map(r => ({ key: r['Record Key'], priority: r['Priority'], category: r['Category'], summary: r['Summary'], action: r['Suggested Action'] })),
    summaries: cur.filter(r => r['AI Status'] === 'OK' && r['Category'] !== 'spam').sort(byPriority)
      .slice(0, Number(cfg.max_summaries_for_ai) || 60)
      .map(r => '[' + r['Category'] + ' | ' + r['Priority'] + ' | ' + r['Sentiment'] + '] ' + r['Summary'])
  };
})() }}

parameters.text:
=Write today's feedback brief.

Window: last {{ $json.stats.window_hours }} hours, {{ $json.stats.total }} messages ({{ $json.stats.total_before }} in the window before).
Categories, now vs before: {{ $json.stats.categories.map(c => c.category + ' ' + c.now + ' vs ' + c.before).join(', ') }}
Spikes: {{ $json.stats.spikes.join(', ') || 'none' }}
Negative sentiment: {{ $json.stats.negative_share }}% (before: {{ $json.stats.negative_share_before }}%)
Churn-risk messages: {{ $json.stats.churn_risk }}
Top keywords: {{ $json.stats.top_keywords.join(', ') || 'none' }}

Message summaries, highest priority first:
{{ $json.stats.summaries.join('\n') }}

parameters.subject:
={{ (() => {
  const s = $('Compute Digest Stats').first().json.stats;
  if (!s.total) return 'Daily feedback digest: no new messages';
  return 'Daily feedback digest: ' + s.total + ' message' + (s.total === 1 ? '' : 's') + (s.spikes.length ? ', spike in ' + s.spikes.join(', ') : '') + (s.churn_risk ? ', ' + s.churn_risk + ' churn risk' : '');
})() }}

parameters.message:
={{ (() => {
  const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  const s = $('Compute Digest Stats').first().json.stats;
  const ran = $('AI · Write Insights').isExecuted;
  const ai = ran ? $('AI · Write Insights').first().json : null;
  const brief = ai?.output?.headline ? ai.output : null;
  const doc = $('Read Feedback Rows').params.documentId ?? {};
  const sheetUrl = doc.cachedResultUrl || (String(doc.value ?? '').startsWith('http') ? String(doc.value) : 'https://docs.google.com/spreadsheets/d/' + doc.value);
  const delta = (now, before) => { const d = now - before; return '<span style="color:#666">' + (d === 0 ? '&plusmn;0' : (d > 0 ? '&#9650; +' : '&#9660; ') + d) + '</span>'; };
  const list = (items) => items.length ? '<ul style="margin:4px 0 12px 18px;padding:0">' + items.map(x => '<li style="margin:2px 0">' + x + '</li>').join('') + '</ul>' : '<p style="color:#888;margin:4px 0 12px 0">None</p>';
  const h3 = (t) => '<h3 style="margin:18px 0 4px 0;font-size:15px">' + t + '</h3>';
  let html = '<div style="font-family:Arial,sans-serif;font-size:14px;color:#222;max-width:720px">' +
    '<h2 style="margin:0 0 4px 0">Daily feedback digest</h2>' +
    '<p style="margin:0 0 14px 0;color:#666">' + esc(s.window_start) + ' &rarr; ' + esc(s.window_end) + ' (last ' + s.window_hours + ' h)</p>';
  if (!s.total) {
    html += '<p>No feedback arrived in this window.' + (s.total_before ? ' <b style="color:#b00020">The window before had ' + s.total_before + ' messages; check that your sources are still sending.</b>' : '') + '</p>';
  } else {
    html += brief ? '<p style="font-size:16px;margin:0 0 12px 0"><b>' + esc(brief.headline) + '</b></p>'
      : '<p style="color:#b26a00">AI insights are unavailable today (' + esc(String(ai?.error ?? 'no output').slice(0, 200)) + '). The numbers below are complete.</p>';
    html += '<table cellpadding="6" style="border-collapse:collapse;margin-bottom:8px">' +
      '<tr><td>Messages</td><td><b>' + s.total + '</b> ' + delta(s.total, s.total_before) + '</td></tr>' +
      '<tr><td>Negative sentiment</td><td><b>' + s.negative_share + '%</b> (before ' + s.negative_share_before + '%)</td></tr>' +
      '<tr><td>Churn risk</td><td><b>' + s.churn_risk + '</b></td></tr>' +
      '<tr><td>Needs review</td><td><b>' + s.needs_review + '</b>' + (s.ai_failed ? ' (incl. ' + s.ai_failed + ' AI failure' + (s.ai_failed === 1 ? '' : 's') + ')' : '') + '</td></tr></table>';
    html += h3('By category') + '<table cellpadding="6" style="border-collapse:collapse">' +
      '<tr style="color:#666;text-align:left"><th>Category</th><th>Now</th><th>Before</th><th>Change</th></tr>' +
      s.categories.map(c => '<tr' + (s.spikes.includes(c.category) ? ' style="background:#fff4e5"' : '') + '><td>' + esc(c.category) + (s.spikes.includes(c.category) ? ' <b style="color:#b26a00">spike</b>' : '') + '</td><td>' + c.now + '</td><td>' + c.before + '</td><td>' + delta(c.now, c.before) + '</td></tr>').join('') + '</table>';
    if (brief) {
      html += h3('Themes') + list(brief.themes.map(t => '<b>' + esc(t.title) + '</b>: ' + esc(t.evidence)));
      html += h3('Emerging issues') + list(brief.emerging_issues.map(esc));
      html += h3('Recommended actions') + list(brief.recommended_actions.map(esc));
    }
    html += h3('Needs attention') + list(s.attention.map(a => '<b>' + esc(a.priority) + '</b> &middot; ' + esc(a.category) + ': ' + esc(a.summary) + (a.action ? ' <span style="color:#0b6e4f">&rarr; ' + esc(a.action) + '</span>' : '') + ' <span style="color:#888;font-size:12px">' + esc(a.key) + '</span>'));
    html += h3('Top keywords') + '<p style="margin:4px 0">' + (s.top_keywords.map(esc).join(', ') || 'None') + '</p>';
  }
  return html + '<p style="margin-top:18px"><a href="' + esc(sheetUrl) + '">Open the Feedback sheet</a></p></div>';
})() }}

